export function prompt(id,args={}) { if(!Object.hasOwn(compiled,id))throw new Error("Unknown prompt id");return compiled[id](args); }
export function systemInstruction(id,common=true) { const stage=id?prompt(id):"";return common?prompt("review:SYSTEM:24")+(stage?"\n\n"+stage:""):stage; }
export const promptIds=Object.freeze(Object.keys(compiled));
